package com.inventra.backend.service; import com.inventra.backend.dto.*; import com.inventra.backend.exception.*; import com.inventra.backend.model.Warehouse; import com.inventra.backend.repository.WarehouseRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class WarehouseService { private final WarehouseRepository repo; public WarehouseService(WarehouseRepository r){repo=r;} public WarehouseResponse create(WarehouseRequest r){if(repo.existsByCodeIgnoreCase(r.code())) throw new IllegalArgumentException("Warehouse code already exists"); Warehouse w=new Warehouse();w.setCode(r.code());w.setName(r.name());w.setLocation(r.location());return map(repo.save(w));} public List<WarehouseResponse> all(){return repo.findAll().stream().map(this::map).toList();} public Warehouse get(String id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Warehouse not found: "+id));} public WarehouseResponse getResponse(String id){return map(get(id));} private WarehouseResponse map(Warehouse w){return new WarehouseResponse(w.getId(),w.getCode(),w.getName(),w.getLocation(),w.isActive());} }
